def _maybe_rewrite_node_to_backend_sdpa(
    node: GraphNode,
    *,
    module: GraphModule,
    modules_by_name: Mapping[str, GraphModule],
    provenance,
    op_name: str,
) -> GraphNode | None:
    if len(node.outputs) != 1 or node.attrs or node.op.name not in modules_by_name:
        return None
    callee = modules_by_name[node.op.name]
    if len(node.inputs) != len(callee.inputs):
        return None
    output_facts = tuple(
        graph_provenance_facts(item)
        for item in provenance.module_summary_provenance.get(callee.name, ())
    )
    if not output_facts:
        return None
    sdpa_facts = [
        fact.value
        for fact in output_facts[0]
        if fact.kind == "sdpa_gqa" and isinstance(fact.value, GraphSdpaGqaFact)
    ]
    if not sdpa_facts:
        return None
    formal_to_actual = {
        formal.name: actual
        for formal, actual in zip(callee.inputs, node.inputs, strict=False)
    }
    local_provenance = provenance.module_local_provenance.get(module.name, {})
    for fact in sdpa_facts:
        try:
            q = formal_to_actual[fact.q]
            k = formal_to_actual[fact.k]
            v = formal_to_actual[fact.v]
            additive_mask = formal_to_actual[fact.additive_mask]
            keep = formal_to_actual[fact.keep]
        except KeyError:
            continue
        extra_bias: GraphOperand | None = None
        if fact.extra_additive_bias is not None:
            if fact.extra_additive_bias not in formal_to_actual:
                continue
            extra_bias = formal_to_actual[fact.extra_additive_bias]
        else:
            additive_prov = _graph_value_ref_provenance(
                additive_mask,
                local_provenance=local_provenance,
            )
            keep_prov = _graph_value_ref_provenance(keep, local_provenance=local_provenance)
            if fact.additive_mask != fact.keep and not fact.precomputed_additive_mask and not _has_additive_mask_from_keep_fact(additive_prov, keep_prov):
                continue
        if fact.default_scale or fact.scale is None:
            scale_operand: GraphOperand = GraphLiteral(value=None, type_expr=TypeNull())
        elif fact.scale.kind == "input" and fact.scale.name in formal_to_actual:
            scale_operand = formal_to_actual[fact.scale.name]
        elif fact.scale.kind == "literal":
            scale_operand = GraphLiteral(
                value=fact.scale.value,
                type_expr=TypeFloat() if isinstance(fact.scale.value, float) else TypeInt(),
            )
        else:
            continue
        sdpa_inputs = (
            q,
            k,
            v,
            additive_mask,
            scale_operand,
            GraphLiteral(value=True, type_expr=TypeBool()),
        )
        if extra_bias is not None:
            sdpa_inputs = sdpa_inputs + (extra_bias,)
        return replace(
            node,
            op=GraphOp(op_name),
            inputs=sdpa_inputs,
            attrs={},
        )
    return None


