        return leaf_text.lstrip("@")
    base_key = "" if base is None else str(base).strip().lstrip("@")
    leaf_key = leaf_text.lstrip("@")
    if not base_key:
        return leaf_key
    if not leaf_key:
        return base_key
    return f"{base_key}.{leaf_key}"


