The file is a zip archive: ``<prefix>/data.pkl`` pickles an ``OrderedDict`` of tensors, each
rebuilt by ``torch._utils._rebuild_tensor_v2`` from a storage whose raw little-endian bytes
live in ``<prefix>/data/<key>``. A restricted unpickler maps exactly those globals to local
stand-ins and refuses everything else, so loading runs no code from the file.
"""

import collections
import pickle
import zipfile

import mlx.core as mx
import numpy as np

# torch storage class -> numpy dtype of its raw bytes (bfloat16 is read as uint16)
_STORAGE_DTYPES = {
    "FloatStorage": np.float32,
    "DoubleStorage": np.float64,
    "HalfStorage": np.float16,
    "BFloat16Storage": np.uint16,
    "LongStorage": np.int64,
    "IntStorage": np.int32,
    "ShortStorage": np.int16,
    "CharStorage": np.int8,
    "ByteStorage": np.uint8,
    "BoolStorage": np.bool_,
}


class _StorageType:
    def __init__(self, name):
        self.name = name


class _Storage:
    def __init__(self, key, storage_type, numel):
        self.key = key
        self.storage_type = storage_type
        self.numel = numel


class _TensorRef:
    def __init__(self, storage, offset, shape, stride):
        self.storage = storage
        self.offset = offset
        self.shape = tuple(int(x) for x in shape)
        self.stride = tuple(int(x) for x in stride)


