"""Machine, git and package provenance, including source-hash pins for third-party packages."""

import hashlib
import importlib.metadata
import importlib.util
import os
import platform
import subprocess
import sys
import time
from pathlib import Path

from .dispatch import ROOT


def command_output(*command):
    try:
        return subprocess.run(command, capture_output=True, text=True, check=True, timeout=10).stdout.strip()
    except (OSError, subprocess.SubprocessError):
        return None


def distribution_version(name):
    try:
        return importlib.metadata.version(name)
    except importlib.metadata.PackageNotFoundError:
        return None


def git_state(root=ROOT):
    try:
        head = subprocess.run(
            ["git", "rev-parse", "HEAD"], cwd=root, capture_output=True, text=True, check=True
        ).stdout.strip()
        status = subprocess.run(
            ["git", "status", "--porcelain"], cwd=root, capture_output=True, text=True, check=True
        ).stdout
        return {"head": head, "dirty": bool(status.strip())}
    except (OSError, subprocess.CalledProcessError) as error:
        return {"head": None, "dirty": None, "error": repr(error)}


def package_directory(package):
    spec = importlib.util.find_spec(package)
    if spec is None or spec.origin is None:
        return None
    return Path(spec.origin).parent


def installed_package_hashes(package, files=None):
    """sha256 of the package's ``*.py`` files (recursive), or only of ``files`` relative to it."""
    directory = package_directory(package)
    if directory is None:
        return None
    paths = (
        [directory / name for name in files]
        if files is not None
        else sorted(path for path in directory.rglob("*.py") if "__pycache__" not in path.parts)
    )
    return {
        path.relative_to(directory).as_posix(): (
            hashlib.sha256(path.read_bytes()).hexdigest() if path.is_file() else None
        )
        for path in paths
    }


def pinned_package_record(pin):
    """Compare an installed package with its pin; ``pin["hashes"]`` lists the files that matter."""
    installed = installed_package_hashes(pin["package"], files=sorted(pin["hashes"]))
    return {
        "repository": pin["repository"],
        "revision": pin.get("revision"),
        "pinned_version": pin["version"],
        "installed_version": distribution_version(pin.get("distribution", pin["package"])),
        "expected_hashes": pin["hashes"],
        "installed_hashes": installed,
        "matches_pin": installed == pin["hashes"],
    }


def machine_snapshot(packages):
    memory = command_output("sysctl", "-n", "hw.memsize")
    return {
        "created": time.strftime("%Y-%m-%dT%H:%M:%S%z"),
        "python": sys.version,
        "executable": sys.executable,
        "platform": platform.platform(),
        "machine": {
            "cpu": command_output("sysctl", "-n", "machdep.cpu.brand_string"),
            "memory_bytes": int(memory) if memory and memory.isdigit() else None,
            "cpu_count": os.cpu_count(),
            "macos": command_output("sw_vers", "-productVersion"),
        },
        "git": git_state(),
        "packages": {name: distribution_version(name) for name in packages},
        "distributions": sorted(
            f"{distribution.metadata['Name']}=={distribution.version}"
            for distribution in importlib.metadata.distributions()
            if distribution.metadata["Name"]
        ),
    }


def file_record(path, chunk_bytes=1 << 24):
    digest = hashlib.sha256()
    size = 0
    with Path(path).open("rb") as handle:
        while chunk := handle.read(chunk_bytes):
            digest.update(chunk)
            size += len(chunk)
    return {"sha256": digest.hexdigest(), "bytes": size}
        "variants": {},
    }
    features = {}
    for variant in variants:
        code = rewrite_common_import(generate_core(variant))
        path = cores / f"axon_core_{variant.replace('-', '_')}.py"
        path.write_text(code)
        features[variant] = code_features(code)
        info["variants"][variant] = {
            "file": path.name,
            **VARIANTS[variant],
            "sha256": _sha256(code.encode()),
            "lines": len(code.splitlines()),
            **features[variant],
        }
    if "unfused" in features:
        base = set(features["unfused"]["helper_calls"])
        for variant, found in features.items():
            info["variants"][variant]["added_vs_unfused"] = sorted(set(found["helper_calls"]) - base)
    (cores / "build-info.json").write_text(json.dumps(info, indent=2) + "\n")
    return cores


def core_path(cores_dir, variant):
    return Path(cores_dir) / f"axon_core_{variant.replace('-', '_')}.py"

