"""Load Ettin checkpoints into the generated MLX cores.

Runtime code: imports neither torch, transformers nor synapse. The generated cores come
from ``python -m scripts.ettin_axon.build``; weights come straight from the Hugging Face
snapshot (``*.safetensors`` through ``mx.load``, or ``pytorch_model.bin`` through the
torch-free reader in ``checkpoint.py``). Parameter names stay the HF names, which are also
the scopes in the ``.axon`` files, so nothing is renamed here.
"""

import hashlib
import json
from pathlib import Path

import mlx.core as mx
import numpy as np

from scripts.bench_common.cores import load_core_class
from scripts.bench_common.dispatch import ROOT

from . import revisions
from .checkpoint import load_torch_bin

DEFAULT_CORES = ROOT / "build/ettin_axon"
TIED_DECODER_KEY = "decoder.weight"
EMBEDDING_KEY = "model.embeddings.tok_embeddings.weight"
SNAPSHOT_FILES = [
    "config.json",
    "tokenizer.json",
    "tokenizer_config.json",
    "special_tokens_map.json",
    "*.safetensors",
    "pytorch_model.bin",
]
ARCH_BY_MODEL_TYPE = {"modernbert": "encoder", "modernbert-decoder": "decoder"}
SUPPORTED_ACTIVATIONS = {"gelu", "gelu_pytorch_tanh", "gelu_new"}


class CheckpointError(ValueError):
    pass


# --- snapshot and config -------------------------------------------------------------------


def snapshot_path(name):
    """A local directory is used as is; a checkpoint name resolves to its pinned revision."""
    path = Path(name).expanduser()
    if path.is_dir():
        return path, None
    from huggingface_hub import snapshot_download

    rid = revisions.repo_id(name)
    rev = revisions.REVISIONS[rid]
    return Path(snapshot_download(rid, revision=rev, allow_patterns=SNAPSHOT_FILES)), {"repo_id": rid, "revision": rev}


def read_json(path):
    return json.loads(Path(path).read_text())


def validate_config(config):
    """Reject config features the .axon files do not implement, instead of running them wrong."""
    model_type = config.get("model_type")
    if model_type not in ARCH_BY_MODEL_TYPE:
        raise CheckpointError(f"unsupported model_type {model_type!r}; expected one of {sorted(ARCH_BY_MODEL_TYPE)}")
    for key in ("hidden_activation", "classifier_activation"):
        value = config.get(key, "gelu")
        if value not in SUPPORTED_ACTIVATIONS:
            raise CheckpointError(f"{key}={value!r} is not supported; expected one of {sorted(SUPPORTED_ACTIVATIONS)}")
    if config.get("rope_scaling"):
        raise CheckpointError("rope_scaling is not supported (default RoPE only)")
    for layer_type, params in (config.get("rope_parameters") or {}).items():
        if (params or {}).get("rope_type", "default") != "default":
            raise CheckpointError(f"rope_parameters[{layer_type!r}] uses rope_type {params['rope_type']!r}; only 'default' is supported")
