    def __call__(self, input_ids, attention_mask=None):
        ids, mask = _ids(input_ids), _mask(attention_mask)
        if mask is None:
            return self._fn(False)(ids) if self.compiled else self._entry(ids, None)
        return self._fn(True)(ids, mask)


class EttinDecoder:
    """ModernBERT-style causal LM with the generated core's KV cache.

    ``forward(ids, attention_mask=None, cache=None, use_cache=False, logits_to_keep=0)`` returns
    ``(logits, cache)``. Without a cache it is one full-sequence pass; with ``use_cache`` the
    returned cache feeds the next call, one or more tokens at a time.
    """

    arch = "decoder"

    def __init__(self, core, entry, config, tokenizer, info, compile=False):
        self.core, self.config, self.tokenizer, self.info = core, config, tokenizer, info
        self._entry = getattr(core, entry)
        self._compiled = {}
        self.compiled = bool(compile)

    def forward(self, input_ids, attention_mask=None, cache=None, use_cache=False, logits_to_keep=0):
        ids, mask = _ids(input_ids), _mask(attention_mask)
        stateful = use_cache or cache is not None
        # The generated Cache.update keeps a preallocated buffer object per layer when this flag
        # is set; a single pass without a cache does not need it.
        object.__setattr__(self.core, "_use_kv_cache", stateful)
        if self.compiled and not stateful:
            key = (mask is not None, int(logits_to_keep))
            if key not in self._compiled:
                entry, keep = self._entry, int(logits_to_keep)
                if mask is None:
                    self._compiled[key] = mx.compile(lambda i: entry(i, None, None, False, keep)[0])
                else:
                    self._compiled[key] = mx.compile(lambda i, m: entry(i, m, None, False, keep)[0])
            logits = self._compiled[key](ids) if mask is None else self._compiled[key](ids, mask)
            return logits, None
        logits, new_cache = self._entry(ids, mask, cache, bool(use_cache), int(logits_to_keep))
        return logits, (new_cache if use_cache else None)

    __call__ = forward


def load_model(name, *, dtype="float32", variant="fused", compile=False, cores_dir=DEFAULT_CORES):
    """Load a checkpoint (pinned name or local snapshot directory) into its generated core."""
    if dtype not in ("float32", "bfloat16"):
        raise ValueError(f"dtype must be float32 or bfloat16, got {dtype!r}")
    snapshot, pinned = snapshot_path(name)
    config = read_json(snapshot / "config.json")
    arch = validate_config(config)
    raw_state, weight_files = load_state(snapshot)
    stored_dtypes = sorted({str(v.dtype) for v in raw_state.values()})
    state = check_state(raw_state, config, arch)
    core_class, entry, manifest = load_core(arch, variant, cores_dir)
    core = core_class.from_state_dict(state, model_config=config, dtype=dtype)
    mx.eval(list(core._flat_tensors.values()))
    info = {
        "name": str(name),
        "snapshot": str(snapshot),
        "pinned": pinned,
        "arch": arch,
        "dtype": dtype,
        "stored_dtypes": stored_dtypes,
        "weight_files": weight_files,
        "variant": variant,
        "compile": bool(compile),
        "build": {k: manifest[k] for k in ("variant", "optimize", "backend_intrinsics", "git")},
        "fast_ops": manifest["archs"][arch]["fast_ops"],
    }
    cls = EttinEncoder if arch == "encoder" else EttinDecoder
    return cls(core, entry, config, EttinTokenizer(snapshot), info, compile=compile)

