"""Load Ettin checkpoints into the generated MLX cores.

Runtime code: imports neither torch, transformers nor synapse. The generated cores come
from ``python -m scripts.ettin_axon.build``; weights come straight from the Hugging Face
snapshot (``*.safetensors`` through ``mx.load``, or ``pytorch_model.bin`` through the
torch-free reader in ``checkpoint.py``). Parameter names stay the HF names, which are also
the scopes in the ``.axon`` files, so nothing is renamed here.
"""

import hashlib
import json
from pathlib import Path

import mlx.core as mx
import numpy as np

from scripts.bench_common.cores import load_core_class
from scripts.bench_common.dispatch import ROOT

from . import revisions
from .checkpoint import load_torch_bin

DEFAULT_CORES = ROOT / "build/ettin_axon"
TIED_DECODER_KEY = "decoder.weight"
EMBEDDING_KEY = "model.embeddings.tok_embeddings.weight"
SNAPSHOT_FILES = [
    "config.json",
    "tokenizer.json",
    "tokenizer_config.json",
    "special_tokens_map.json",
    "*.safetensors",
    "pytorch_model.bin",
]
ARCH_BY_MODEL_TYPE = {"modernbert": "encoder", "modernbert-decoder": "decoder"}
SUPPORTED_ACTIVATIONS = {"gelu", "gelu_pytorch_tanh", "gelu_new"}


class CheckpointError(ValueError):
    pass


# --- snapshot and config -------------------------------------------------------------------


def snapshot_path(name):
    """A local directory is used as is; a checkpoint name resolves to its pinned revision."""
    path = Path(name).expanduser()
    if path.is_dir():
        return path, None
    from huggingface_hub import snapshot_download

    rid = revisions.repo_id(name)
    rev = revisions.REVISIONS[rid]
    return Path(snapshot_download(rid, revision=rev, allow_patterns=SNAPSHOT_FILES)), {"repo_id": rid, "revision": rev}


def read_json(path):
    return json.loads(Path(path).read_text())


def validate_config(config):
    """Reject config features the .axon files do not implement, instead of running them wrong."""
    model_type = config.get("model_type")
    if model_type not in ARCH_BY_MODEL_TYPE:
        raise CheckpointError(f"unsupported model_type {model_type!r}; expected one of {sorted(ARCH_BY_MODEL_TYPE)}")
    for key in ("hidden_activation", "classifier_activation"):
        value = config.get(key, "gelu")
        if value not in SUPPORTED_ACTIVATIONS:
            raise CheckpointError(f"{key}={value!r} is not supported; expected one of {sorted(SUPPORTED_ACTIVATIONS)}")
    if config.get("rope_scaling"):
        raise CheckpointError("rope_scaling is not supported (default RoPE only)")
    for layer_type, params in (config.get("rope_parameters") or {}).items():
        if (params or {}).get("rope_type", "default") != "default":
            raise CheckpointError(f"rope_parameters[{layer_type!r}] uses rope_type {params['rope_type']!r}; only 'default' is supported")
    hidden, heads = config["hidden_size"], config["num_attention_heads"]
    if hidden % heads:
        raise CheckpointError(f"hidden_size {hidden} is not divisible by num_attention_heads {heads}")
    if config.get("head_dim") not in (None, hidden // heads):
        raise CheckpointError(f"head_dim {config['head_dim']} differs from hidden_size // num_attention_heads")
    layer_types = config.get("layer_types")
    if layer_types is not None:
        if len(layer_types) != config["num_hidden_layers"]:
            raise CheckpointError("layer_types length differs from num_hidden_layers")
        unknown = set(layer_types) - {"full_attention", "sliding_attention"}
        if unknown:
            raise CheckpointError(f"unsupported layer_types {sorted(unknown)}")
    return ARCH_BY_MODEL_TYPE[model_type]


# --- weights -------------------------------------------------------------------------------


def load_state(snapshot):
    """Read the snapshot's weights as ``{hf_name: mx.array}``, in their stored dtype."""
    snapshot = Path(snapshot)
    shards = sorted(snapshot.glob("*.safetensors"))
    if shards:
        state = {}
        for shard in shards:
            state.update(mx.load(str(shard)))
        return state, [s.name for s in shards]
    binary = snapshot / "pytorch_model.bin"
    if binary.is_file():
        return load_torch_bin(binary), [binary.name]
    raise CheckpointError(f"{snapshot}: no *.safetensors or pytorch_model.bin")


def expected_shapes(config, arch):
    """HF parameter names and shapes for this config, honoring every bias flag."""
    d, f, v = config["hidden_size"], config["intermediate_size"], config["vocab_size"]
    attention_bias = config.get("attention_bias", False)
    mlp_bias = config.get("mlp_bias", False)
    norm_bias = config.get("norm_bias", False)
    shapes = {}

    def linear(name, out_dim, in_dim, bias):
        shapes[f"{name}.weight"] = (out_dim, in_dim)
        if bias:
            shapes[f"{name}.bias"] = (out_dim,)

    def norm(name):
        shapes[f"{name}.weight"] = (d,)
        if norm_bias:
            shapes[f"{name}.bias"] = (d,)

    shapes[EMBEDDING_KEY] = (v, d)
    norm("model.embeddings.norm")
    for i in range(config["num_hidden_layers"]):
        layer = f"model.layers.{i}"
        if i != 0:
            norm(f"{layer}.attn_norm")
        if arch == "encoder":
            linear(f"{layer}.attn.Wqkv", 3 * d, d, attention_bias)
        else:
            for proj in ("q_proj", "k_proj", "v_proj"):
                linear(f"{layer}.attn.{proj}", d, d, attention_bias)
        linear(f"{layer}.attn.Wo", d, d, attention_bias)
        norm(f"{layer}.mlp_norm")
        linear(f"{layer}.mlp.Wi", 2 * f, d, mlp_bias)
        linear(f"{layer}.mlp.Wo", d, f, mlp_bias)
    norm("model.final_norm")
    head = "head" if arch == "encoder" else "lm_head"
    linear(f"{head}.dense", d, d, config.get("classifier_bias", False))
    norm(f"{head}.norm")
    if config.get("decoder_bias", True):
        shapes["decoder.bias"] = (v,)
    if not config.get("tie_word_embeddings", True):
        shapes[TIED_DECODER_KEY] = (v, d)
    return shapes


def check_state(state, config, arch):
    """Fail on any missing, unexpected or misshapen key; drop the tied decoder weight.

    The .axon files read the decoder weight from the embedding (``weight_path=``), so a stored
    ``decoder.weight`` is accepted only when it has the embedding's shape and is then dropped.
    """
    expected = expected_shapes(config, arch)
    state = dict(state)
    tied = config.get("tie_word_embeddings", True)
    if tied and TIED_DECODER_KEY in state:
        stored = state.pop(TIED_DECODER_KEY)
        if tuple(stored.shape) != expected[EMBEDDING_KEY]:
            raise CheckpointError(f"tied {TIED_DECODER_KEY} has shape {tuple(stored.shape)}, embedding expects {expected[EMBEDDING_KEY]}")
    if not tied:
        raise CheckpointError("tie_word_embeddings=false is not supported: the .axon files tie the decoder by reference")
    missing = sorted(set(expected) - set(state))
    unexpected = sorted(set(state) - set(expected))
    misshapen = sorted(
        f"{k}: {tuple(state[k].shape)} != {expected[k]}" for k in set(expected) & set(state) if tuple(state[k].shape) != expected[k]
    )
    if missing or unexpected or misshapen:
        raise CheckpointError(f"checkpoint does not match the config: missing={missing} unexpected={unexpected} misshapen={misshapen}")
    return state


# --- generated cores -----------------------------------------------------------------------


def core_manifest(variant="fused", cores_dir=DEFAULT_CORES):
    path = Path(cores_dir) / variant / "manifest.json"
    if not path.is_file():
        raise FileNotFoundError(f"no generated cores at {path.parent}; run: python -m scripts.ettin_axon.build")
    return read_json(path)


def load_core(arch, variant="fused", cores_dir=DEFAULT_CORES):
    """Return ``(core_class, entry_name, manifest)``; refuse cores built from an older .axon."""
    manifest = core_manifest(variant, cores_dir)
    info = manifest["archs"][arch]
    source = ROOT / info["axon_source"]
    if source.is_file() and hashlib.sha256(source.read_bytes()).hexdigest() != info["axon_sha256"]:
        raise RuntimeError(f"{source} changed since the cores were built; run: python -m scripts.ettin_axon.build")
    core_class = load_core_class(Path(cores_dir) / variant / info["file"], info["class_name"])
    return core_class, info["entry"], manifest


# --- tokenizer -----------------------------------------------------------------------------


class EttinTokenizer:
    """``tokenizer.json`` plus the special-token rules HF applies on top of it.

    When ``tokenizer_config.json`` sets ``add_bos_token``/``add_eos_token`` (the decoders),
    those flags decide the special tokens, as HF tokenizers that support them do; otherwise
    (the encoders) the ``tokenizer.json`` post-processor adds ``[CLS] ... [SEP]``.
    transformers 5.x drops these flags for the Ettin decoders and adds no BOS, which the
    decoders need (see wiki/ettin-axon-mlx.md).
    """

    def __init__(self, snapshot):
        from tokenizers import Tokenizer

        snapshot = Path(snapshot)
        self.backend = Tokenizer.from_file(str(snapshot / "tokenizer.json"))
        config_path = snapshot / "tokenizer_config.json"
        config = read_json(config_path) if config_path.is_file() else {}
        self.flags = {k: bool(config[k]) for k in ("add_bos_token", "add_eos_token") if k in config}

        def token_id(key):
            token = config.get(key)
            if isinstance(token, dict):
                token = token.get("content")
            return None if token is None else self.backend.token_to_id(token)

        self.mask_token = config.get("mask_token")
        self.mask_token_id = token_id("mask_token")
        self.pad_token_id = token_id("pad_token")
        self.bos_token_id = token_id("bos_token") if "bos_token" in config else token_id("cls_token")
        self.eos_token_id = token_id("eos_token") if "eos_token" in config else token_id("sep_token")

    def encode(self, text):
        if not self.flags:
            return self.backend.encode(text).ids
        ids = self.backend.encode(text, add_special_tokens=False).ids
        if self.flags.get("add_bos_token"):
            ids = [self.bos_token_id, *ids]
        if self.flags.get("add_eos_token"):
            ids = [*ids, self.eos_token_id]
        return ids

    def decode(self, ids, skip_special_tokens=True):
        return self.backend.decode(list(ids), skip_special_tokens=skip_special_tokens)

    def pad(self, sequences):
        """Right-pad id lists into ``(ids, attention_mask)`` int32 arrays."""
        length = max(len(s) for s in sequences)
        ids = np.full((len(sequences), length), self.pad_token_id, dtype=np.int32)
        mask = np.zeros((len(sequences), length), dtype=np.int32)
        for row, seq in enumerate(sequences):
            ids[row, : len(seq)] = seq
            mask[row, : len(seq)] = 1
        return ids, mask


# --- models --------------------------------------------------------------------------------


def _ids(input_ids):
    return mx.array(np.asarray(input_ids), dtype=mx.int64) if not isinstance(input_ids, mx.array) else input_ids.astype(mx.int64)


def _mask(attention_mask):
    if attention_mask is None:
        return None
    return mx.array(np.asarray(attention_mask), dtype=mx.int32) if not isinstance(attention_mask, mx.array) else attention_mask


class EttinEncoder:
    """ModernBERT masked LM: ``model(ids, attention_mask)`` returns ``(logits, last_hidden_state)``."""

    arch = "encoder"

    def __init__(self, core, entry, config, tokenizer, info, compile=False):
        self.core, self.config, self.tokenizer, self.info = core, config, tokenizer, info
        self._entry = getattr(core, entry)
        self._compiled = {}
        self.compiled = bool(compile)

    def _fn(self, masked):
        if not self.compiled:
            return self._entry
        if masked not in self._compiled:
            entry = self._entry
            self._compiled[masked] = mx.compile(entry if masked else (lambda ids: entry(ids, None)))
        return self._compiled[masked]

    def __call__(self, input_ids, attention_mask=None):
        ids, mask = _ids(input_ids), _mask(attention_mask)
        if mask is None:
            return self._fn(False)(ids) if self.compiled else self._entry(ids, None)
        return self._fn(True)(ids, mask)


class EttinDecoder:
    """ModernBERT-style causal LM with the generated core's KV cache.

    ``forward(ids, attention_mask=None, cache=None, use_cache=False, logits_to_keep=0)`` returns
    ``(logits, cache)``. Without a cache it is one full-sequence pass; with ``use_cache`` the
    returned cache feeds the next call, one or more tokens at a time.
    """

    arch = "decoder"

    def __init__(self, core, entry, config, tokenizer, info, compile=False):
        self.core, self.config, self.tokenizer, self.info = core, config, tokenizer, info
        self._entry = getattr(core, entry)
        self._compiled = {}
        self.compiled = bool(compile)

    def forward(self, input_ids, attention_mask=None, cache=None, use_cache=False, logits_to_keep=0):
        ids, mask = _ids(input_ids), _mask(attention_mask)
        stateful = use_cache or cache is not None
        # The generated Cache.update keeps a preallocated buffer object per layer when this flag
        # is set; a single pass without a cache does not need it.
        object.__setattr__(self.core, "_use_kv_cache", stateful)
        if self.compiled and not stateful:
            key = (mask is not None, int(logits_to_keep))
            if key not in self._compiled:
                entry, keep = self._entry, int(logits_to_keep)
                if mask is None:
                    self._compiled[key] = mx.compile(lambda i: entry(i, None, None, False, keep)[0])
                else:
                    self._compiled[key] = mx.compile(lambda i, m: entry(i, m, None, False, keep)[0])
            logits = self._compiled[key](ids) if mask is None else self._compiled[key](ids, mask)
            return logits, None
        logits, new_cache = self._entry(ids, mask, cache, bool(use_cache), int(logits_to_keep))
        return logits, (new_cache if use_cache else None)

    __call__ = forward


def load_model(name, *, dtype="float32", variant="fused", compile=False, cores_dir=DEFAULT_CORES):
    """Load a checkpoint (pinned name or local snapshot directory) into its generated core."""
    if dtype not in ("float32", "bfloat16"):
        raise ValueError(f"dtype must be float32 or bfloat16, got {dtype!r}")
    snapshot, pinned = snapshot_path(name)
    config = read_json(snapshot / "config.json")
    arch = validate_config(config)
    raw_state, weight_files = load_state(snapshot)
    stored_dtypes = sorted({str(v.dtype) for v in raw_state.values()})
    state = check_state(raw_state, config, arch)
    core_class, entry, manifest = load_core(arch, variant, cores_dir)
    core = core_class.from_state_dict(state, model_config=config, dtype=dtype)
    mx.eval(list(core._flat_tensors.values()))
    info = {
        "name": str(name),
        "snapshot": str(snapshot),
        "pinned": pinned,
        "arch": arch,
        "dtype": dtype,
        "stored_dtypes": stored_dtypes,
        "weight_files": weight_files,
        "variant": variant,
        "compile": bool(compile),
        "build": {k: manifest[k] for k in ("variant", "optimize", "backend_intrinsics", "git")},
        "fast_ops": manifest["archs"][arch]["fast_ops"],
    }
    cls = EttinEncoder if arch == "encoder" else EttinDecoder
    return cls(core, entry, config, EttinTokenizer(snapshot), info, compile=compile)

