class EttinEncoder:
    """ModernBERT masked LM: ``model(ids, attention_mask)`` returns ``(logits, last_hidden_state)``;
    ``model.embed(...)`` returns only the last hidden state and never computes the logits."""

    arch = "encoder"

    def __init__(self, core, entry, config, tokenizer, info, compile=False):
        self.core, self.config, self.tokenizer, self.info = core, config, tokenizer, info
        self._entry = getattr(core, entry)
        self._compiled = {}
        self.compiled = bool(compile)

    def _run(self, output, input_ids, attention_mask):
        """``output`` None returns both outputs, 0 the logits, 1 the hidden state."""
        ids, mask = _ids(input_ids), _mask(attention_mask)
        if not self.compiled:
            result = self._entry(ids, mask)
            return result if output is None else result[output]
        key = (output, mask is not None)
        if key not in self._compiled:
            entry = self._entry
            pick = (lambda r: tuple(r)) if output is None else (lambda r: r[output])
            fn = (lambda i, m: pick(entry(i, m))) if mask is not None else (lambda i: pick(entry(i, None)))
            self._compiled[key] = mx.compile(fn)
        return self._compiled[key](ids, mask) if mask is not None else self._compiled[key](ids)

    def __call__(self, input_ids, attention_mask=None):
        return self._run(None, input_ids, attention_mask)

    def embed(self, input_ids, attention_mask=None):
        return self._run(1, input_ids, attention_mask)

